"""Generates icons/phosphor/phosphor.odin: one constant per Phosphor icon, embedding its six weights
with #load (only icons the program references end up in the binary).

Usage: python3 -I gen_phosphor.py <third_party/phosphor dir> <output .odin file>
"""

import pathlib
import re
import sys

src = pathlib.Path(sys.argv[1])
out = pathlib.Path(sys.argv[2])

WEIGHTS = ["thin", "light", "regular", "bold", "fill", "duotone"]

names = sorted(p.stem for p in (src / "regular").glob("*.svg"))
rel = "../../third_party/phosphor"

lines = [
    "// Generated by third_party/scripts/gen_phosphor.py from Phosphor Icons (MIT, see",
    "// third_party/phosphor/LICENSE). Do not edit.",
    "package phosphor",
    "",
    'import "../../icons"',
    "",
]
seen = set()
for name in names:
    ident = re.sub(r"[^A-Za-z0-9]+", "_", name).upper()
    if ident[0].isdigit():
        ident = "_" + ident
    assert ident not in seen, ident
    seen.add(ident)
    lines.append(f"{ident} :: icons.Icon {{")
    lines.append(f'\tname = "{name}",')
    lines.append("\tsvg = {")
    for w in WEIGHTS:
        file = f"{name}.svg" if w == "regular" else f"{name}-{w}.svg"
        assert (src / w / file).exists(), (w, file)
        lines.append(f'\t\t.{w.capitalize()} = #load("{rel}/{w}/{file}", string),')
    lines.append("\t},")
    lines.append("}")
    lines.append("")

out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(lines))
print(f"generated {len(names)} icons into {out}")
